const MCP_URL =
  "https://kmysinxpdkeszrtdyhid.supabase.co/functions/v1/gralha-indicadores-mcp/mcp";
const ADMIN_URL =
  "https://kmysinxpdkeszrtdyhid.supabase.co/functions/v1/gralha-portal-admin";
const DEFAULT_OPENAI_MODEL = "gpt-5-mini";
const OPENAI_TIMEOUT_MS = 25_000;
const SOURCE_AVAILABILITY_CACHE_MS = 15_000;
let sourceAvailabilityCache = { expiresAt: 0, value: null };

const SECURITY_HEADERS = {
  "Content-Security-Policy":
    "default-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'; img-src 'self' data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'",
  "Referrer-Policy": "no-referrer",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=()",
};

function response(
  body,
  status = 200,
  contentType = "text/html; charset=UTF-8",
) {
  return new Response(body, {
    status,
    headers: {
      ...SECURITY_HEADERS,
      "Content-Type": contentType,
      "Cache-Control": contentType.startsWith("text/html")
        ? "no-store"
        : "no-store, max-age=0",
    },
  });
}

function json(payload, status = 200) {
  return response(
    JSON.stringify(payload),
    status,
    "application/json; charset=UTF-8",
  );
}

function configured(env) {
  return Boolean(
    env.SUPABASE_URL && env.SUPABASE_PUBLISHABLE_KEY && env.OPENAI_API_KEY,
  );
}

function authConfigured(env) {
  return Boolean(env.SUPABASE_URL && env.SUPABASE_PUBLISHABLE_KEY);
}

function supabaseUrl(env, path) {
  return `${String(env.SUPABASE_URL).replace(/\/$/, "")}${path}`;
}

async function parseJson(request) {
  const length = Number(request.headers.get("content-length") || "0");
  if (length > 55000) throw new Error("payload_too_large");
  return request.json();
}

async function login(request, env) {
  if (!authConfigured(env))
    return json(
      { error: "A configuração segura do portal ainda não foi concluída." },
      503,
    );
  let body;
  try {
    body = await parseJson(request);
  } catch {
    return json({ error: "Dados de acesso inválidos." }, 400);
  }
  const email =
    typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
  const password = typeof body.password === "string" ? body.password : "";
  if (!email || !password || email.length > 254 || password.length > 512) {
    return json({ error: "Informe o e-mail e a senha." }, 400);
  }
  const auth = await fetch(
    supabaseUrl(env, "/auth/v1/token?grant_type=password"),
    {
      method: "POST",
      headers: {
        apikey: env.SUPABASE_PUBLISHABLE_KEY,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ email, password }),
    },
  );
  if (!auth.ok)
    return json(
      {
        error:
          "E-mail ou senha incorretos. Confira os dados e tente novamente.",
      },
      401,
    );
  const session = await auth.json();
  return json({
    access_token: session.access_token,
    refresh_token: session.refresh_token,
    expires_at: session.expires_at,
    user: { email: session.user?.email || email },
  });
}

async function recoverPassword(request, env) {
  if (!authConfigured(env))
    return json(
      { error: "A configuração segura do portal ainda não foi concluída." },
      503,
    );
  let body;
  try {
    body = await parseJson(request);
  } catch {
    return json({ error: "Informe um e-mail válido." }, 400);
  }
  const email =
    typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
  if (!email || email.length > 254 || !email.includes("@")) {
    return json({ error: "Informe um e-mail válido." }, 400);
  }

  const redirectTo = `${new URL(request.url).origin}/reset-password`;
  const auth = await fetch(
    supabaseUrl(
      env,
      `/auth/v1/recover?redirect_to=${encodeURIComponent(redirectTo)}`,
    ),
    {
      method: "POST",
      headers: {
        apikey: env.SUPABASE_PUBLISHABLE_KEY,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ email }),
    },
  );
  if (!auth.ok)
    console.error("password_recovery_failed", { status: auth.status });

  return json({
    message:
      "Se o e-mail estiver autorizado, você receberá as instruções para criar uma nova senha.",
  });
}

async function updatePassword(request, env) {
  if (!authConfigured(env))
    return json(
      { error: "A configuração segura do portal ainda não foi concluída." },
      503,
    );
  const accessToken = bearer(request);
  if (!accessToken || accessToken.length > 8192) {
    return json(
      {
        error:
          "Este link de recuperação é inválido ou expirou. Solicite um novo.",
      },
      401,
    );
  }

  let body;
  try {
    body = await parseJson(request);
  } catch {
    return json({ error: "Informe uma nova senha válida." }, 400);
  }
  const password = typeof body.password === "string" ? body.password : "";
  if (password.length < 12 || password.length > 512) {
    return json(
      { error: "A nova senha deve ter pelo menos 12 caracteres." },
      400,
    );
  }

  const auth = await fetch(supabaseUrl(env, "/auth/v1/user"), {
    method: "PUT",
    headers: {
      apikey: env.SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ password }),
  });
  if (!auth.ok) {
    return json(
      {
        error:
          "Não foi possível atualizar a senha. O link pode ter expirado; solicite um novo.",
      },
      401,
    );
  }
  return json({
    message:
      "Senha criada com sucesso. Agora você já pode entrar no Gralha Indicadores.",
  });
}

async function refresh(request, env) {
  if (!authConfigured(env))
    return json({ error: "Portal não configurado." }, 503);
  let body;
  try {
    body = await parseJson(request);
  } catch {
    return json({ error: "Sessão inválida." }, 400);
  }
  const refreshToken =
    typeof body.refresh_token === "string" ? body.refresh_token : "";
  if (!refreshToken || refreshToken.length > 4096)
    return json({ error: "Sessão inválida." }, 401);
  const auth = await fetch(
    supabaseUrl(env, "/auth/v1/token?grant_type=refresh_token"),
    {
      method: "POST",
      headers: {
        apikey: env.SUPABASE_PUBLISHABLE_KEY,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ refresh_token: refreshToken }),
    },
  );
  if (!auth.ok)
    return json({ error: "Sua sessão expirou. Entre novamente." }, 401);
  const session = await auth.json();
  return json({
    access_token: session.access_token,
    refresh_token: session.refresh_token,
    expires_at: session.expires_at,
    user: { email: session.user?.email || "" },
  });
}

function bearer(request) {
  const header = request.headers.get("Authorization") || "";
  return header.startsWith("Bearer ") ? header.slice(7).trim() : "";
}

async function authenticatedUser(request, env, signal) {
  const accessToken = bearer(request);
  if (!accessToken || accessToken.length > 8192) return null;
  const result = await fetch(supabaseUrl(env, "/auth/v1/user"), {
    signal,
    headers: {
      apikey: env.SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${accessToken}`,
    },
  });
  if (!result.ok) return null;
  const user = await result.json().catch(() => null);
  return user?.id ? { id: user.id, email: user.email || "", accessToken } : null;
}

async function rest(env, token, path, init = {}) {
  return fetch(supabaseUrl(env, `/rest/v1/${path}`), {
    ...init,
    headers: {
      apikey: env.SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
      ...(init.headers || {}),
    },
  });
}

async function authorizeHistory(request, env) {
  // A valid Auth session can outlive a portal profile's deactivation. Consult
  // the current profile on every request, including cached chat responses.
  // Use the user's JWT (never service_role) so the database still applies RLS.
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const auth = await authenticatedUser(request, env, controller.signal);
    if (!auth) return { error: json({ error: "Sua sessão expirou. Entre novamente." }, 401) };
    const query = new URLSearchParams({
      select: "id,status,access_role",
      id: `eq.${auth.id}`,
      limit: "1",
    });
    const result = await rest(env, auth.accessToken, `profiles?${query}`, {
      signal: controller.signal,
      cache: "no-store",
    });
    if (!result.ok) {
      if (result.status === 401) return { error: json({ error: "Sua sessão expirou. Entre novamente." }, 401) };
      throw new Error("profile_lookup_failed");
    }
    const rows = await result.json();
    if (!Array.isArray(rows)) throw new Error("invalid_profile_response");
    const profile = rows[0];
    const roles = ["ceo", "cso", "cmo", "store_director", "team_manager"];
    if (rows.length !== 1 || profile?.id !== auth.id || profile.status !== "active" || !roles.includes(profile.access_role)) {
      return { error: json({ error: "Seu acesso ao portal não está ativo. Procure um administrador." }, 403) };
    }
    return { auth };
  } catch {
    // Fail closed without forwarding upstream bodies, identities or tokens.
    return { error: json({ error: "Não foi possível validar seu acesso. Tente novamente mais tarde." }, 503) };
  } finally {
    clearTimeout(timeout);
  }
}

async function conversationsApi(request, env, url) {
  const authorization = await authorizeHistory(request, env);
  if (authorization.error) return authorization.error;
  const auth = authorization.auth;
  const baseMatch = url.pathname.match(/^\/api\/conversations(?:\/([0-9a-f-]{36})(?:\/messages)?)?$/i);
  if (!baseMatch) return json({ error: "Rota não encontrada." }, 404);
  const conversationId = baseMatch[1] || "";
  const isMessages = url.pathname.endsWith("/messages");

  if (request.method === "GET" && !conversationId) {
    const result = await rest(env, auth.accessToken, `conversations?select=id,title,created_at,updated_at&user_id=eq.${auth.id}&order=updated_at.desc&limit=100`);
    return json(result.ok ? await result.json() : { error: "Não foi possível carregar o histórico." }, result.status);
  }
  if (request.method === "POST" && !conversationId) {
    const body = await parseJson(request).catch(() => null);
    const title = typeof body?.title === "string" ? body.title.replace(/\s+/g, " ").trim().slice(0, 160) : "";
    if (!title) return json({ error: "Informe um título válido." }, 400);
    const result = await rest(env, auth.accessToken, "conversations", {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({ user_id: auth.id, title }),
    });
    const rows = await result.json().catch(() => []);
    return json(result.ok ? { conversation: rows[0] } : { error: "Não foi possível criar a conversa." }, result.status);
  }
  if (request.method === "GET" && conversationId && isMessages) {
    const result = await rest(env, auth.accessToken, `conversation_messages?select=id,role,content,visualization,created_at&conversation_id=eq.${conversationId}&order=id.asc&limit=500`);
    return json(result.ok ? await result.json() : { error: "Não foi possível abrir a conversa." }, result.status);
  }
  if (request.method === "PATCH" && conversationId && !isMessages) {
    const body = await parseJson(request).catch(() => null);
    const title = typeof body?.title === "string" ? body.title.replace(/\s+/g, " ").trim().slice(0, 160) : "";
    if (!title) return json({ error: "Informe um título válido." }, 400);
    const result = await rest(env, auth.accessToken, `conversations?id=eq.${conversationId}&user_id=eq.${auth.id}`, {
      method: "PATCH",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({ title, updated_at: new Date().toISOString() }),
    });
    return json(result.ok ? { updated: true } : { error: "Não foi possível renomear a conversa." }, result.status);
  }
  if (request.method === "DELETE" && conversationId && !isMessages) {
    const result = await rest(env, auth.accessToken, `conversations?id=eq.${conversationId}&user_id=eq.${auth.id}`, { method: "DELETE" });
    // PostgREST returns 204 on deletion; a JSON response needs a body-capable status.
    return json(result.ok ? { deleted: true } : { error: "Não foi possível excluir a conversa." }, result.ok ? 200 : result.status);
  }
  return json({ error: "Método não permitido." }, 405);
}

async function adminApi(request, env, url) {
  const token = bearer(request);
  if (!token) return json({ error: "Sua sessão expirou. Entre novamente." }, 401);
  const suffix = url.pathname.replace(/^\/api\/admin/, "") || "/me";
  if (!/^\/(?:me|teams|users(?:\/[0-9a-f-]{36})?)$/i.test(suffix)) return json({ error: "Rota não encontrada." }, 404);
  const upstream = await fetch(ADMIN_URL + suffix, {
    method: request.method,
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: ["POST", "PATCH"].includes(request.method) ? await request.text() : undefined,
  });
  return json(await upstream.json().catch(() => ({ error: "Serviço indisponível." })), upstream.status);
}

function outputText(payload) {
  if (typeof payload.output_text === "string" && payload.output_text.trim()) {
    return payload.output_text.trim();
  }
  const parts = [];
  for (const item of Array.isArray(payload.output) ? payload.output : []) {
    for (const block of Array.isArray(item?.content) ? item.content : []) {
      if (typeof block?.text === "string") parts.push(block.text);
    }
  }
  return parts.join("\n").trim();
}

function parseJsonString(value) {
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function lastMcpValue(payload) {
  const calls = (Array.isArray(payload.output) ? payload.output : [])
    .filter((item) => item?.type === "mcp_call" && !item.error)
    .reverse();
  for (const call of calls) {
    const parsed = parseJsonString(call.output);
    const candidates = [
      parsed?.structuredContent,
      parsed?.result?.structuredContent,
      parsed?.result,
      parsed,
    ];
    for (const candidate of candidates) {
      if (
        candidate &&
        typeof candidate === "object" &&
        (candidate.summary ||
          candidate.ranking ||
          candidate.visualization ||
          candidate.error)
      ) {
        return candidate;
      }
    }
    const content = parsed?.content ?? parsed?.result?.content;
    for (const block of Array.isArray(content) ? content : []) {
      const value = parseJsonString(block?.text);
      if (
        value &&
        typeof value === "object" &&
        (value.summary || value.ranking || value.visualization || value.error)
      )
        return value;
    }
  }
  return null;
}

const MONTHS = [
  "janeiro",
  "fevereiro",
  "marco",
  "abril",
  "maio",
  "junho",
  "julho",
  "agosto",
  "setembro",
  "outubro",
  "novembro",
  "dezembro",
];

function normalizedQuestion(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function monthlyPeriodFromMessages(messages) {
  const monthPattern = MONTHS.join("|");
  const currentYear = Number(todayInSaoPaulo().slice(0, 4));

  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (messages[index]?.role !== "user") continue;
    const text = normalizedQuestion(messages[index]?.content);
    const match = text.match(
      new RegExp(`\\b(${monthPattern})\\b(?:\\s+de)?(?:\\s+(20\\d{2})\\b)?`),
    );
    if (!match) continue;
    const monthIndex = MONTHS.indexOf(match[1]);
    let year = match[2] ? Number(match[2]) : null;
    if (!year) {
      for (let contextIndex = index - 1; contextIndex >= 0; contextIndex -= 1) {
        if (messages[contextIndex]?.role !== "user") continue;
        const contextText = normalizedQuestion(messages[contextIndex]?.content);
        const contextYear = contextText.match(/\\b(20\\d{2})\\b/);
        if (contextYear) {
          year = Number(contextYear[1]);
          break;
        }
      }
    }
    year ||= currentYear;
    const month = monthIndex + 1;
    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    const paddedMonth = String(month).padStart(2, "0");
    return {
      start: `${year}-${paddedMonth}-01`,
      end: `${year}-${paddedMonth}-${String(lastDay).padStart(2, "0")}`,
      label: `${match[1]} de ${year}`,
    };
  }
  return null;
}

function fastIntent(messages) {
  const latest = normalizedQuestion(messages.at(-1)?.content);
  const period = monthlyPeriodFromMessages(messages);
  if (!period) return null;

  const isProposal = /\bpropost/.test(latest);
  const recentUserMessages = messages
    .slice(0, -1)
    .filter((message) => message?.role === "user")
    .slice(-4)
    .map((message) => normalizedQuestion(message?.content));
  const recentUserContext = recentUserMessages.join(" ");
  const hasProposalContext = isProposal || /\bpropost/.test(recentUserContext);
  const asksChart = /\b(grafico|visualiz)/.test(latest);

  if (/\bfunil\b/.test(latest)) {
    const asksTeamFunnel =
      /\b(equipe|times?|separad|cada)\b/.test(latest) ||
      /\bfunil\s+(?:da|do|de)\s+\S/.test(latest);
    return {
      type: asksTeamFunnel ? "team_funnel_chart" : "funnel_current_chart",
      period,
    };
  }

  const asksCurrentStageCount =
    /\b(quanto|quantos|quanta|quantas|quantidade|total|todos|todas|numero)\b/.test(latest) &&
    /\b(captacao|oportunidad|visit|propost|negociacao|fechamento|agend)/.test(
      latest,
    ) &&
    !(
      /\bpropost/.test(latest) &&
      (/\bgerad/.test(latest) || /\bcriad/.test(latest))
    );
  if (asksCurrentStageCount) {
    return { type: "team_stage_snapshot", period };
  }

  if (asksChart && hasProposalContext) {
    const previousFocus = [...recentUserMessages].reverse().find((message) =>
      /\b(equipe|status|propost)|\bem aberto\b|\b(perdid|ganh)/.test(message)
    ) || "";
    return {
      type: /\bequipe/.test(previousFocus)
        ? "proposal_team_chart"
        : "proposal_status_chart",
      period,
    };
  }
  if (
    hasProposalContext &&
    /\bequipe/.test(latest) &&
    /(separ|distrib|por equipe)/.test(latest)
  ) {
    return { type: "proposal_team_snapshot", period };
  }
  if (
    hasProposalContext &&
    /\bstatus\b/.test(latest) &&
    /(separ|distrib|por status)/.test(latest)
  ) {
    return { type: "proposal_status_snapshot", period };
  }
  if (
    isProposal &&
    /\b(atualmente|agora|etapa atual|na etapa)\b/.test(latest)
  ) {
    return { type: "proposal_current_snapshot", period };
  }
  if (
    /\bem aberto\b/.test(latest) &&
    hasProposalContext
  ) {
    return { type: "proposal_open_snapshot", period };
  }
  const asksGeneratedProposals =
    isProposal &&
    (/\bpropostas?\b[^.?!]{0,80}\b(gerad|criad)/.test(latest) ||
      /\b(gerad|criad)[a-z]*\b[^.?!]{0,80}\bpropostas?\b/.test(latest));
  if (asksGeneratedProposals) {
    return { type: "proposal_generated", period };
  }

  const asksSalesTotal =
    /\bvendas?\b/.test(latest) &&
    /(quantas|quantidade|total)/.test(latest) &&
    !/(equipe|corretor|bairro|ranking|vgv|ticket|compar|graf)/.test(latest);
  return asksSalesTotal ? { type: "monthly_sales_total", period } : null;
}

function indicatorSource(messages) {
  const latest = normalizedQuestion(messages.at(-1)?.content);
  if (
    /\b(propost|negoci|funil|etapa|status|captacao|oportunidade|visita|fechamento|agend|agenci|placa|veiculo|loja|imovel|lead)/.test(
      latest,
    )
  ) {
    return "vista_funnel";
  }
  if (/\bbairro/.test(latest)) return "sales_neighborhood_detail";
  if (
    /\b(venda|vgv|ticket|corretor|equipe|ranking|campeao)/.test(
      latest,
    )
  ) {
    return "sales";
  }
  return null;
}

async function callMcpToolDirect(accessToken, name, args, timeoutMs = 35_000) {
  let response;
  try {
    response = await fetch(MCP_URL, {
      method: "POST",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: crypto.randomUUID(),
        method: "tools/call",
        params: { name, arguments: args },
      }),
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch {
    return { error: "backend_unreachable" };
  }
  const payload = await response.json().catch(() => null);
  if (!response.ok || payload?.error) {
    return {
      error: response.status === 401
        ? "backend_auth_rejected"
        : "backend_unreachable",
    };
  }
  const result = payload?.result;
  if (result?.structuredContent && typeof result.structuredContent === "object") {
    return result.structuredContent;
  }
  for (const block of Array.isArray(result?.content) ? result.content : []) {
    const value = parseJsonString(block?.text);
    if (value && typeof value === "object") return value;
  }
  return { error: "invalid_upstream_contract" };
}

async function sourceAvailability(accessToken) {
  if (
    sourceAvailabilityCache.value &&
    sourceAvailabilityCache.expiresAt > Date.now()
  ) {
    return sourceAvailabilityCache.value;
  }
  const value = await callMcpToolDirect(
    accessToken,
    "verificar_disponibilidade_fontes",
    {},
    4_000,
  );
  if (!value?.error) {
    sourceAvailabilityCache = {
      expiresAt: Date.now() + SOURCE_AVAILABILITY_CACHE_MS,
      value,
    };
  }
  return value;
}

function payloadWithMcpValue(value) {
  return {
    output: [
      {
        type: "mcp_call",
        output: JSON.stringify({ structuredContent: value }),
      },
    ],
  };
}

function fallbackAnswerFromTool(payload) {
  const value = lastMcpValue(payload);
  if (!value || typeof value !== "object") return "";
  if (value.error) {
    if (value.error === "source_circuit_open") {
      const retryAfter = Number(value.retry_after_seconds);
      const retryText = Number.isFinite(retryAfter) && retryAfter > 0
        ? ` Uma nova tentativa será liberada em até ${Math.ceil(retryAfter)} segundos.`
        : "";
      return `${value.detail || "A fonte de dados está em verificação temporária."}${retryText}`;
    }
    const messages = {
      backend_unreachable:
        "Não consegui consultar o Vista agora. Tente novamente em instantes.",
      vista_funnel_unavailable:
        "O Vista não concluiu esta consulta. Tente novamente em instantes.",
      backend_auth_rejected:
        "A consulta foi interrompida por uma falha de autenticação entre os serviços.",
      team_reference_unavailable:
        "Os dados do funil foram consultados, mas a associação por equipe não está disponível agora.",
    };
    return messages[value.error] ||
      (typeof value.detail === "string" && value.detail.trim()
        ? value.detail.trim()
        : "Não foi possível concluir esta consulta agora.");
  }
  if (typeof value.detail === "string" && value.detail.trim()) {
    return value.detail.trim();
  }

  const proposal = value.summary?.proposal;
  if (!proposal || typeof proposal !== "object") return "";
  const openTotal = Number(
    proposal.created_deals_in_proposal_stage_with_open_status,
  );
  const currentTotal = Number(
    proposal.created_deals_currently_in_proposal,
  );
  const breakdown = Array.isArray(proposal.team_breakdown)
    ? proposal.team_breakdown
    : [];
  const openBreakdown = breakdown.filter(
    (row) => Number(row?.open_deals_count || 0) > 0,
  );

  if (value.group_by === "equipe") {
    const coverage = proposal.team_coverage || {};
    const assignedOpen = Number(coverage.assigned_open || 0);
    const unassignedOpen = Number(coverage.unassigned_open || 0);
    if (!openBreakdown.length) {
      return [
        "Nenhuma proposta em aberto retornou uma equipe ou um responsável com vínculo gerencial válido.",
        Number.isFinite(openTotal) && Number.isFinite(currentTotal)
          ? `No total, são ${openTotal} negócios em aberto e ${currentTotal} atualmente na etapa Proposta.`
          : "",
        "Essa é uma fotografia atual dos negócios criados no período, não o total histórico de propostas geradas.",
      ]
        .filter(Boolean)
        .join("\n\n");
    }

    const rows = openBreakdown.slice(0, 20).map((row) => {
      const team = String(row?.team || "Equipe não identificada");
      const open = Number(row?.open_deals_count || 0);
      const current = Number(row?.current_stage_deals_count || 0);
      return `- ${team}: ${open} em aberto; ${current} atualmente na etapa Proposta`;
    });
    const coverageText = unassignedOpen
      ? `${assignedOpen} de ${openTotal} propostas em aberto têm equipe atribuída; ${unassignedOpen} ficaram sem vínculo de equipe.`
      : `${assignedOpen} de ${openTotal} propostas em aberto têm equipe atribuída.`;
    return [
      "Propostas em aberto por equipe:",
      rows.join("\n"),
      coverageText,
      "Os números representam a fotografia atual dos negócios criados no período, não todas as entradas históricas na etapa Proposta.",
    ].join("\n\n");
  }

  if (Number.isFinite(openTotal) && Number.isFinite(currentTotal)) {
    return `Há ${openTotal} negócios com status “Em aberto” na etapa Proposta e ${currentTotal} negócios atualmente nessa etapa. Essa fotografia atual não representa todas as entradas históricas em Proposta.`;
  }
  return "";
}

function referencedOperationalCount(value) {
  const matches = normalizedQuestion(value).match(/\b\d{1,4}\b/g) || [];
  for (const match of matches) {
    const number = Number(match);
    if (number > 0 && number < 1900) return number;
  }
  return null;
}

function proposalStatusRows(value) {
  const rows = value?.summary?.proposal
    ?.current_proposal_stage_status_breakdown;
  if (!Array.isArray(rows)) return [];
  return rows.flatMap((row) => {
    const status = typeof row?.status === "string" ? row.status.trim() : "";
    const count = Number(row?.deals_count);
    return status && Number.isFinite(count) && count >= 0
      ? [{ status, count }]
      : [];
  });
}

function funnelStageRows(value) {
  const rows = value?.summary?.current_stage_breakdown;
  if (!Array.isArray(rows)) return [];
  const stageOrder = (stage) => {
    const normalized = normalizedQuestion(stage);
    const known = [
      [/lead|captacao|cadastro/, 10],
      [/atendimento|qualificacao|contato/, 20],
      [/oportunidade|interesse/, 30],
      [/visita/, 40],
      [/proposta/, 50],
      [/negociacao/, 60],
      [/fechamento/, 70],
      [/ganho|vendido|venda/, 80],
    ];
    return known.find(([pattern]) => pattern.test(normalized))?.[1] ?? 999;
  };
  return rows.flatMap((row, index) => {
    const stage = typeof row?.stage === "string" ? row.stage.trim() : "";
    const count = Number(row?.deals_count);
    return stage && Number.isFinite(count) && count >= 0
      ? [{ stage, count, index }]
      : [];
  }).sort((a, b) => stageOrder(a.stage) - stageOrder(b.stage) || a.index - b.index);
}

function funnelCurrentAnswer(value, period) {
  const rows = funnelStageRows(value);
  const total = Number(value?.summary?.created_deals);
  if (!rows.length) return "";
  const totalText = Number.isFinite(total)
    ? `${total.toLocaleString("pt-BR")} negócios criados em ${period.label}`
    : `Negócios criados em ${period.label}`;
  return `${totalText}, distribuídos pelas etapas atuais conforme o gráfico. Esta é uma fotografia do momento, não uma taxa de conversão histórica entre etapas.`;
}

function funnelCurrentVisualization(value, period) {
  const rows = funnelStageRows(value);
  if (!rows.length) return null;
  return safeVisualization({
    type: "funnel",
    title: `Funil comercial — fotografia atual de ${period.label}`,
    metric: "deals_count",
    unit: "deals",
    series: rows.map((row) => ({
      label: row.stage,
      value: row.count,
      sales_count: row.count,
    })),
    footnote:
      "Distribuição atual dos negócios criados no período. Não representa conversão histórica entre etapas.",
  });
}

function teamFunnelRows(value) {
  const rows = value?.summary?.team_funnel?.team_breakdown;
  if (!Array.isArray(rows)) return [];
  return rows.flatMap((row) => {
    const team = typeof row?.team === "string" ? row.team.trim() : "";
    const total = Number(row?.deals_count);
    const stages = Array.isArray(row?.stage_breakdown)
      ? row.stage_breakdown.flatMap((stageRow, index) => {
        const stage = typeof stageRow?.stage === "string"
          ? stageRow.stage.trim()
          : "";
        const count = Number(stageRow?.deals_count);
        return stage && Number.isFinite(count) && count >= 0
          ? [{ stage, count, index }]
          : [];
      })
      : [];
    return team && Number.isFinite(total) && total >= 0
      ? [{ team, total, stages }]
      : [];
  });
}

function mentionedTeam(rows, question) {
  const normalized = normalizedQuestion(question);
  return rows.find((row) => {
    const fullTeam = normalizedQuestion(row.team);
    const shortTeam = fullTeam.replace(/^(?:equipe|time)\s+/, "").trim();
    return [fullTeam, shortTeam].filter(Boolean).some((team) =>
      new RegExp(`(^|\\b)${escapeRegExp(team)}(\\b|$)`).test(normalized)
    );
  }) || null;
}

function requestedStage(question) {
  const normalized = normalizedQuestion(question);
  const definitions = [
    { pattern: /\bagend/, match: /agend/, label: "Agendamento" },
    { pattern: /\bvisit/, match: /visit/, label: "Visita" },
    { pattern: /\bcaptacao|\blead|\bcadastro/, match: /captacao|lead|cadastro/, label: "Captação" },
    { pattern: /\boportunidade/, match: /oportunidade|interesse/, label: "Oportunidade" },
    { pattern: /\bpropost/, match: /propost/, label: "Proposta" },
    { pattern: /\bnegociacao/, match: /negociacao/, label: "Negociação" },
    { pattern: /\bfechamento/, match: /fechamento|ganho|vendido|venda/, label: "Fechamento" },
  ];
  return definitions.find((definition) => definition.pattern.test(normalized)) || null;
}

function orderedTeamStages(stages) {
  const wrapped = { summary: { current_stage_breakdown: stages.map((row) => ({
    stage: row.stage,
    deals_count: row.count,
  })) } };
  return funnelStageRows(wrapped);
}

function teamFunnelAnswer(value, period, question) {
  const rows = teamFunnelRows(value);
  if (!rows.length) return "";
  const selected = mentionedTeam(rows, question);
  if (selected) {
    return `${selected.total.toLocaleString("pt-BR")} negócios criados em ${period.label} estão atribuídos à equipe ${selected.team}, distribuídos pelas etapas atuais conforme o funil. Esta é uma fotografia do momento.`;
  }
  const coverage = value?.summary?.team_funnel?.team_coverage;
  const assigned = Number(coverage?.assigned_deals);
  const total = Number(coverage?.created_deals_total);
  const coverageText = Number.isFinite(assigned) && Number.isFinite(total)
    ? ` ${assigned.toLocaleString("pt-BR")} de ${total.toLocaleString("pt-BR")} negócios possuem equipe atribuída.`
    : "";
  return `O funil de ${period.label} está separado em ${rows.length.toLocaleString("pt-BR")} equipes.${coverageText}`;
}

function teamFunnelVisualization(value, period, question) {
  const rows = teamFunnelRows(value);
  if (!rows.length) return null;
  const selected = mentionedTeam(rows, question);
  if (selected) {
    const stages = orderedTeamStages(selected.stages);
    return safeVisualization({
      type: "funnel",
      title: `Funil comercial — ${selected.team} — ${period.label}`,
      metric: "deals_count",
      unit: "deals",
      series: stages.map((row) => ({ label: row.stage, value: row.count })),
      footnote: "Fotografia atual dos negócios criados no período e atribuídos à equipe.",
    });
  }
  return safeVisualization({
    type: "multi_funnel",
    title: `Funil comercial por equipe — ${period.label}`,
    metric: "deals_count",
    unit: "deals",
    groups: rows.slice(0, 24).map((row) => ({
      label: row.team,
      series: orderedTeamStages(row.stages).map((stage) => ({
        label: stage.stage,
        value: stage.count,
      })),
    })),
    footnote: "Cada quadro apresenta a etapa atual dos negócios atribuídos à respectiva equipe.",
  });
}

function teamStageAnswer(value, period, question) {
  const rows = teamFunnelRows(value);
  const requested = requestedStage(question);
  if (!rows.length || !requested) return "";
  const selected = mentionedTeam(rows, question);
  const globalRows = funnelStageRows(value).map((row) => ({
    stage: row.stage,
    count: row.count,
  }));
  const stageRows = selected ? selected.stages : globalRows;
  const matched = stageRows.filter((row) =>
    requested.match.test(normalizedQuestion(row.stage))
  );
  const count = matched.reduce((total, row) => total + row.count, 0);
  const actualStages = [...new Set(matched.map((row) => row.stage))];
  const scope = selected ? ` da equipe ${selected.team}` : "";
  if (!matched.length) {
    return `Não há uma etapa atual correspondente a “${requested.label}”${scope} entre os negócios criados em ${period.label}.`;
  }
  const stageLabel = actualStages.join(" / ");
  return `${count.toLocaleString("pt-BR")} negócios${scope}, criados em ${period.label}, estão atualmente na etapa ${stageLabel}. Isso representa a fotografia atual, não o total histórico de passagens pela etapa.`;
}
function proposalStatusAnswer(value, period) {
  const proposal = value?.summary?.proposal;
  const currentTotal = Number(proposal?.created_deals_currently_in_proposal);
  const rows = proposalStatusRows(value);
  if (!Number.isFinite(currentTotal) || !rows.length) return "";
  const breakdown = rows
    .map((row) => `${row.count.toLocaleString("pt-BR")} ${row.status}`)
    .join(" e ");
  return `${currentTotal.toLocaleString("pt-BR")} negócios criados em ${period.label} estão atualmente na etapa Proposta — ${breakdown}.`;
}

function proposalStatusVisualization(value, period) {
  const rows = proposalStatusRows(value);
  if (!rows.length) return null;
  return safeVisualization({
    type: "bar",
    title: `Negócios em Proposta por status — ${period.label}`,
    metric: "sales_count",
    unit: "sales",
    series: rows.map((row) => ({
      label: row.status,
      value: row.count,
      sales_count: row.count,
    })),
    footnote:
      `Fotografia atual dos negócios criados em ${period.label}; não representa o histórico de entradas na etapa Proposta.`,
  });
}

function proposalTeamVisualization(value, period) {
  const upstreamValue = value?.visualization;
  const upstream = safeVisualization(
    upstreamValue && Array.isArray(upstreamValue.series)
      ? {
        ...upstreamValue,
        series: upstreamValue.series.filter(
          (row) => Number(row?.value || 0) > 0,
        ),
      }
      : upstreamValue,
  );
  if (upstream) return upstream;
  const rows = value?.summary?.proposal?.team_breakdown;
  const teamVisualization = safeVisualization({
    type: "bar",
    title: `Propostas em aberto por equipe — ${period.label}`,
    metric: "sales_count",
    unit: "sales",
    series: (Array.isArray(rows) ? rows : [])
      .filter((row) => Number(row?.open_deals_count || 0) > 0)
      .map((row) => ({
        label: String(row?.team || "Equipe não identificada"),
        value: Number(row?.open_deals_count || 0),
        sales_count: Number(row?.open_deals_count || 0),
      })),
    footnote: "Fotografia atual; a cobertura de atribuição é informada no texto.",
  });
  if (teamVisualization) return teamVisualization;

  const coverage = value?.summary?.proposal?.team_coverage;
  const openTotal = Number(
    value?.summary?.proposal?.created_deals_in_proposal_stage_with_open_status,
  );
  const assignedOpen = Number(coverage?.assigned_open);
  const unassignedOpen = Number(coverage?.unassigned_open);
  if (
    !Number.isFinite(openTotal) ||
    !Number.isFinite(assignedOpen) ||
    !Number.isFinite(unassignedOpen) ||
    assignedOpen + unassignedOpen !== openTotal
  ) return null;

  return safeVisualization({
    type: "bar",
    title: `Cobertura de atribuição das propostas em aberto — ${period.label}`,
    metric: "sales_count",
    unit: "sales",
    series: [
      {
        label: "Com equipe atribuída",
        value: assignedOpen,
        sales_count: assignedOpen,
      },
      {
        label: "Sem vínculo de equipe",
        value: unassignedOpen,
        sales_count: unassignedOpen,
      },
    ],
    footnote:
      "A ausência de vínculo gerencial impede a distribuição confiável por equipe.",
  });
}

function safeVisualization(value) {
  if (value?.type === "multi_funnel" && Array.isArray(value.groups)) {
    const groups = value.groups.slice(0, 24).flatMap((group) => {
      const label = typeof group?.label === "string"
        ? group.label.trim().slice(0, 80)
        : "";
      const series = Array.isArray(group?.series)
        ? group.series.slice(0, 10).flatMap((item) => {
          const itemLabel = typeof item?.label === "string"
            ? item.label.trim().slice(0, 80)
            : "";
          const numericValue = Number(item?.value);
          return itemLabel && Number.isFinite(numericValue) && numericValue >= 0
            ? [{ label: itemLabel, value: numericValue }]
            : [];
        })
        : [];
      return label && series.length ? [{ label, series }] : [];
    });
    if (!groups.length) return null;
    return {
      type: "multi_funnel",
      title: typeof value.title === "string"
        ? value.title.slice(0, 140)
        : "Funil por equipe",
      metric: "deals_count",
      unit: "deals",
      groups,
      footnote: typeof value.footnote === "string"
        ? value.footnote.slice(0, 320)
        : "",
    };
  }
  if (
    !value ||
    !["bar", "funnel"].includes(value.type) ||
    !Array.isArray(value.series)
  )
    return null;
  const series = value.series.slice(0, 10).flatMap((item) => {
    const label =
      typeof item?.label === "string" ? item.label.trim().slice(0, 80) : "";
    const numericValue = Number(item?.value);
    if (!label || !Number.isFinite(numericValue) || numericValue < 0) return [];
    return [
      {
        label,
        value: numericValue,
        sales_count: Number.isFinite(Number(item.sales_count))
          ? Number(item.sales_count)
          : null,
        vgv: Number.isFinite(Number(item.vgv)) ? Number(item.vgv) : null,
      },
    ];
  });
  if (!series.length) return null;
  return {
    type: value.type,
    title:
      typeof value.title === "string"
        ? value.title.slice(0, 140)
        : "Comparativo",
    metric: value.metric === "vgv" ? "vgv" : "sales_count",
    unit: value.unit === "BRL"
      ? "BRL"
      : value.unit === "deals"
      ? "deals"
      : "sales",
    series,
    footnote:
      typeof value.footnote === "string" ? value.footnote.slice(0, 320) : "",
  };
}

function todayInSaoPaulo() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date());
  const values = Object.fromEntries(
    parts.map((part) => [part.type, part.value]),
  );
  return `${values.year}-${values.month}-${values.day}`;
}

async function generateChat(request, env) {
  if (!configured(env))
    return json(
      { error: "A configuração segura do portal ainda não foi concluída." },
      503,
    );
  const accessToken = bearer(request);
  if (!accessToken || accessToken.length > 8192)
    return json({ error: "Sessão ausente. Entre novamente." }, 401);

  const authCheck = await fetch(supabaseUrl(env, "/auth/v1/user"), {
    headers: {
      apikey: env.SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${accessToken}`,
    },
  });
  if (!authCheck.ok)
    return json(
      { error: "Sua sessão expirou. Entre novamente para continuar." },
      401,
    );

  let body;
  try {
    body = await parseJson(request);
  } catch {
    return json({ error: "Pergunta inválida." }, 400);
  }

  const messages = Array.isArray(body.messages) ? body.messages.slice(-10) : [];
  const valid =
    messages.length > 0 &&
    messages.every(
      (message) =>
        (message?.role === "user" || message?.role === "assistant") &&
        typeof message?.content === "string" &&
        message.content.trim().length > 0 &&
        message.content.length <= 4000,
    );
  if (!valid) return json({ error: "Digite uma pergunta válida." }, 400);
  const latestQuestion = messages.at(-1)?.content || "";
  const currentDate = todayInSaoPaulo();

  const directIntent = fastIntent(messages);
  if (directIntent) {
    const isSales = directIntent.type === "monthly_sales_total";
    const directValue = await callMcpToolDirect(
      accessToken,
      isSales ? "consultar_ranking_vendas" : "consultar_funil_vista",
      {
        data_inicio: directIntent.period.start,
        data_fim: directIntent.period.end,
        ...(isSales
          ? { criterio: "quantidade", agrupar_por: "corretor", top_n: 1 }
          : {
            agrupar_por: [
                "proposal_team_snapshot",
                "proposal_team_chart",
                "team_funnel_chart",
                "team_stage_snapshot",
              ].includes(directIntent.type)
              ? "equipe"
              : "nenhum",
          }),
      },
    );
    if (directValue?.error) {
      sourceAvailabilityCache = { expiresAt: 0, value: null };
      if (directValue.error === "backend_auth_rejected") {
        return json(
          { error: "Sua sessão expirou. Renovando o acesso aos indicadores." },
          401,
        );
      }
      if (directIntent.type === "proposal_generated") {
        const operationalStatus = fallbackAnswerFromTool(
          payloadWithMcpValue(directValue),
        );
        return json({
          answer:
            `A quantidade exata de propostas geradas em ${directIntent.period.label} não está disponível porque o Vista não fornece o histórico de entrada na etapa. ${operationalStatus}`,
          visualization: null,
        });
      }
      return json({
        answer: fallbackAnswerFromTool(payloadWithMcpValue(directValue)),
        visualization: null,
      });
    }
    if (isSales) {
      const total = Number(directValue?.summary?.official_sales);
      if (Number.isFinite(total)) {
        const effectiveEnd = directValue?.coverage?.effective?.end;
        const partial = effectiveEnd && effectiveEnd !== directIntent.period.end
          ? `, até ${effectiveEnd.split("-").reverse().join("/")}`
          : "";
        return json({
          answer:
            `Foram ${total.toLocaleString("pt-BR")} vendas em ${directIntent.period.label}${partial}.`,
          visualization: null,
        });
      }
    } else if (directIntent.type === "funnel_current_chart") {
      const answer = funnelCurrentAnswer(directValue, directIntent.period);
      const visualization = funnelCurrentVisualization(
        directValue,
        directIntent.period,
      );
      if (answer && visualization) {
        return json({ answer, visualization });
      }
    } else if (directIntent.type === "team_funnel_chart") {
      const answer = teamFunnelAnswer(
        directValue,
        directIntent.period,
        latestQuestion,
      );
      const visualization = teamFunnelVisualization(
        directValue,
        directIntent.period,
        latestQuestion,
      );
      if (answer && visualization) {
        return json({ answer, visualization });
      }
    } else if (directIntent.type === "team_stage_snapshot") {
      const answer = teamStageAnswer(
        directValue,
        directIntent.period,
        latestQuestion,
      );
      if (answer) return json({ answer, visualization: null });
    } else if (
      directIntent.type === "proposal_generated" ||
      directIntent.type === "proposal_current_snapshot" ||
      directIntent.type === "proposal_open_snapshot" ||
      directIntent.type === "proposal_status_snapshot" ||
      directIntent.type === "proposal_status_chart"
    ) {
      const proposal = directValue?.summary?.proposal;
      const openTotal = Number(
        proposal?.created_deals_in_proposal_stage_with_open_status,
      );
      const currentTotal = Number(
        proposal?.created_deals_currently_in_proposal,
      );
      if (Number.isFinite(openTotal) && Number.isFinite(currentTotal)) {
        if (directIntent.type === "proposal_current_snapshot") {
          return json({
            answer:
              `Há ${currentTotal.toLocaleString("pt-BR")} negócios criados em ${directIntent.period.label} atualmente na etapa Proposta. Desses, ${openTotal.toLocaleString("pt-BR")} estão com status “Em aberto”.`,
            visualization: null,
          });
        }
        if (directIntent.type === "proposal_open_snapshot") {
          const referenced = referencedOperationalCount(latestQuestion);
          const update = Number.isFinite(referenced) && referenced !== openTotal
            ? `A fotografia do Vista foi atualizada durante a conversa: agora são ${openTotal.toLocaleString("pt-BR")} negócios em aberto na etapa Proposta.`
            : `Desses negócios, ${openTotal.toLocaleString("pt-BR")} estão com status “Em aberto” na etapa Proposta.`;
          return json({
            answer: update,
            visualization: null,
          });
        }
        if (
          directIntent.type === "proposal_status_snapshot" ||
          directIntent.type === "proposal_status_chart"
        ) {
          const answer = proposalStatusAnswer(
            directValue,
            directIntent.period,
          );
          if (answer) {
            const referenced = referencedOperationalCount(latestQuestion);
            const update = Number.isFinite(referenced) &&
                referenced !== currentTotal
              ? `A fotografia do Vista foi atualizada durante a conversa: o total atual é ${currentTotal.toLocaleString("pt-BR")}.

`
              : "";
            return json({
              answer: `${update}${answer}`,
              visualization: directIntent.type === "proposal_status_chart"
                ? proposalStatusVisualization(
                  directValue,
                  directIntent.period,
                )
                : null,
            });
          }
        }
        return json({
          answer:
            `Não é possível determinar quantas propostas foram geradas em ${directIntent.period.label} com os dados integrados atuais. Entre os negócios criados no mês, ${openTotal} estão em aberto na etapa Proposta e ${currentTotal} estão atualmente nessa etapa.`,
          visualization: null,
        });
      }
    } else {
      const answer = fallbackAnswerFromTool(payloadWithMcpValue(directValue));
      if (answer) {
        const proposal = directValue?.summary?.proposal;
        const openTotal = Number(
          proposal?.created_deals_in_proposal_stage_with_open_status,
        );
        const referenced = referencedOperationalCount(latestQuestion);
        const update = [
            "proposal_team_snapshot",
            "proposal_team_chart",
          ].includes(directIntent.type) &&
            Number.isFinite(referenced) &&
            Number.isFinite(openTotal) &&
            referenced !== openTotal
          ? `A fotografia do Vista foi atualizada durante a conversa: agora são ${openTotal.toLocaleString("pt-BR")} negócios em aberto na etapa Proposta.

`
          : "";
        return json({
          answer: `${update}${answer}`,
          visualization: directIntent.type === "proposal_team_chart"
            ? proposalTeamVisualization(directValue, directIntent.period)
            : null,
        });
      }
    }
  }

  const requiredSource = indicatorSource(messages);
  if (requiredSource) {
    const availability = await sourceAvailability(accessToken);
    if (availability?.error) {
      if (availability.error === "backend_auth_rejected") {
        return json(
          { error: "Sua sessão expirou. Renovando o acesso aos indicadores." },
          401,
        );
      }
      return json({
        answer:
          "Não foi possível confirmar o retorno das APIs agora. A análise foi interrompida antes do processamento generativo.",
        visualization: null,
      });
    }
    const sourceState = availability?.sources?.[requiredSource];
    if (sourceState?.available !== true) {
      const retryAfter = Number(sourceState.retry_after_seconds);
      const retryText = Number.isFinite(retryAfter) && retryAfter > 0
        ? ` Nova verificação em até ${Math.ceil(retryAfter)} segundos.`
        : "";
      return json({
        answer:
          `A fonte necessária está temporariamente indisponível. A análise foi interrompida antes do processamento generativo.${retryText}`,
        visualization: null,
      });
    }
  }

  const openAiModel = env.OPENAI_MODEL || DEFAULT_OPENAI_MODEL;
  let ai;
  try {
    ai = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${env.OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      signal: AbortSignal.timeout(OPENAI_TIMEOUT_MS),
      body: JSON.stringify({
        model: openAiModel,
        store: false,
        max_output_tokens: 900,
        reasoning: { effort: "low" },
        instructions: [
        "Você é o assistente de indicadores comerciais da Gralha Imóveis.",
        "Responda em português do Brasil. Comece pelo número, ranking ou conclusão solicitada, sem bordões ou introduções padronizadas.",
        "Para perguntas sobre vendas oficiais, rankings de vendas, corretores, bairros, VGV ou ticket, use consultar_ranking_vendas. Para perguntas sobre negócios cadastrados no período, status geral, etapa atual do funil, visitas, agendamentos ou propostas, use consultar_funil_vista. Todo pedido de etapa ou funil por equipe deve chamar consultar_funil_vista com agrupar_por=equipe e, quando houver uma equipe específica, também equipe=<nome>. Preserve o período da conversa. Nunca use consultar_ranking_vendas para responder sobre etapas do funil.",
        "Nunca invente valores, nomes, posições, critérios ou períodos.",
        `A data atual em São Paulo é ${currentDate}. Nunca trate datas posteriores como já realizadas; para ano corrente, consulte do primeiro dia do ano até a data atual.`,
        "Em perguntas objetivas, responda em uma ou duas frases. Só acrescente período, critério, fonte ou cobertura quando isso evitar uma interpretação errada ou quando o usuário pedir detalhes.",
        "Em avaliações gerenciais, separe fatos, comparação, leitura executiva e ação recomendada, mas apenas quando os dados sustentarem essas conclusões. No funil, diferencie negócios criados no período, etapa atual, status geral e eventos históricos de entrada em etapa. Uma contagem na etapa Visita representa negócios atualmente nessa etapa, não visitas realizadas. Nunca trate negócios atualmente em Proposta como propostas geradas no período. Não atribua causas nem afirme conversão, eventos históricos de visitas, propostas geradas ou tempo entre etapas sem dados correspondentes.",
        "Quando uma métrica histórica não existir, apresente primeiro a fotografia atual verificada, em no máximo 80 palavras, e esclareça a diferença em uma frase. Não use prefixos padronizados. Se a ferramenta retornar erro, não transforme valores ausentes em análise: informe a falha em uma frase curta e solicite nova tentativa.",
        "Quando o usuário pedir Top N, envie top_n=N à ferramenta. O padrão é Top 10.",
        "Nunca produza gráficos com caracteres, código Python, matplotlib ou instruções para gerar imagem. O portal renderiza a visualização estruturada devolvida pela ferramenta.",
        "Quando útil, use listas curtas em texto simples e evite repetir a mesma confirmação.",
        "Se a ferramenta não trouxer dados suficientes, explique objetivamente o que falta.",
        ].join(" "),
        input: messages.map(({ role, content }) => ({ role, content })),
        tools: [
          {
            type: "mcp",
            server_label: "gralha_indicadores",
            server_description:
              "Consulta somente leitura aos rankings de vendas e à coorte de negócios do funil Vista autorizados da Gralha Imóveis.",
            server_url: MCP_URL,
            authorization: accessToken,
            allowed_tools: [
              "consultar_ranking_vendas",
              "consultar_funil_vista",
            ],
            require_approval: "never",
          },
        ],
      }),
    });
  } catch (error) {
    const timedOut =
      error instanceof DOMException &&
      (error.name === "TimeoutError" || error.name === "AbortError");
    console.error("openai_request_error", {
      kind: timedOut ? "timeout" : "network_error",
      model: openAiModel,
    });
    return json(
      {
        error: timedOut
          ? "A análise demorou mais do que o esperado. Tente novamente."
          : "Não foi possível acessar a análise inteligente agora. Tente novamente em instantes.",
      },
      timedOut ? 504 : 502,
    );
  }

  const payload = await ai.json().catch(() => ({}));
  if (!ai.ok) {
    console.error("openai_request_failed", {
      status: ai.status,
      requestId: ai.headers.get("x-request-id"),
    });
    if (ai.status === 429)
      return json(
        {
          error:
            "O limite temporário de consultas foi atingido. Aguarde um pouco e tente novamente.",
        },
        429,
      );
    return json(
      {
        error:
          "Não foi possível consultar os indicadores agora. Tente novamente em instantes.",
      },
      502,
    );
  }
  const structured = lastMcpValue(payload);
  if (structured?.error) {
    sourceAvailabilityCache = { expiresAt: 0, value: null };
  }
  const answer = structured?.error
    ? fallbackAnswerFromTool(payload)
    : outputText(payload) || fallbackAnswerFromTool(payload);
  if (!answer) {
    console.error("openai_response_without_text", {
      status: payload.status || null,
      incompleteReason: payload.incomplete_details?.reason || null,
      outputTypes: (Array.isArray(payload.output) ? payload.output : [])
        .map((item) => item?.type || "unknown")
        .slice(0, 12),
    });
    return json(
      {
        error:
          "A consulta foi concluída, mas a resposta não pôde ser montada. Tente novamente.",
      },
      502,
    );
  }
  const visualizationRequested =
    /gr[aá]fic|visual|compar|ranking|top\s*\d/i.test(latestQuestion);
  const visualization = visualizationRequested
    ? safeVisualization(structured?.visualization)
    : null;
  return json({ answer, visualization });
}

async function persistChatResult(request, env) {
  const body = await request.clone().json().catch(() => null);
  const conversationId = typeof body?.conversation_id === "string" ? body.conversation_id : "";
  const requestId = typeof body?.request_id === "string" ? body.request_id : "";
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  // Backward compatibility for API clients that do not use portal history.
  // The browser portal always supplies both IDs and receives persistence.
  if (!uuid.test(conversationId) || !uuid.test(requestId)) {
    return generateChat(request, env);
  }
  const authorization = await authorizeHistory(request, env);
  if (authorization.error) return authorization.error;
  const auth = authorization.auth;

  const cached = await rest(env, auth.accessToken, `conversation_messages?select=content,visualization&conversation_id=eq.${conversationId}&role=eq.assistant&request_id=eq.${requestId}&limit=1`);
  if (cached.ok) {
    const rows = await cached.json().catch(() => []);
    if (rows[0]?.content) return json({ answer: rows[0].content, visualization: rows[0].visualization || null });
  }

  const generated = await generateChat(request, env);
  if (!generated.ok) return generated;
  const payload = await generated.clone().json().catch(() => null);
  const latest = Array.isArray(body?.messages) ? body.messages.at(-1) : null;
  if (!payload?.answer || latest?.role !== "user") return generated;
  const records = [
    { conversation_id: conversationId, user_id: auth.id, role: "user", content: String(latest.content).slice(0, 12000), visualization: null, request_id: requestId },
    { conversation_id: conversationId, user_id: auth.id, role: "assistant", content: String(payload.answer).slice(0, 12000), visualization: payload.visualization || null, request_id: requestId },
  ];
  const saved = await rest(env, auth.accessToken, "conversation_messages", {
    method: "POST",
    headers: { Prefer: "resolution=ignore-duplicates,return=minimal" },
    body: JSON.stringify(records),
  });
  if (saved.ok) {
    await rest(env, auth.accessToken, `conversations?id=eq.${conversationId}&user_id=eq.${auth.id}`, {
      method: "PATCH",
      body: JSON.stringify({ updated_at: new Date().toISOString() }),
    });
  } else {
    console.error("conversation_persist_failed", { status: saved.status });
  }
  return generated;
}

