    async function ask(value){const question=(value||draft.value).trim();if(!question||busy||!session)return;busy=true;send.disabled=true;showError(chatError,"");try{await ensureConversation(question);welcome.classList.add("hidden");conversation.classList.remove("hidden");$("home-button").classList.add("visible");messages.push({role:"user",content:question});addMessage("user",question);draft.value="";typing(true);const requestBody={messages:messages.slice(-12),conversation_id:activeConversationId,request_id:crypto.randomUUID()};let res=await chatApi(requestBody,session.access_token);if(res.status===401&&await renew())res=await chatApi(requestBody,session.access_token);const data=await res.json();if(!res.ok||!data.answer){if(res.status===401){save(null);messages=[];conversation.textContent="";showLogin()}showError(chatError,data.error||"Não foi possível obter a resposta agora.");return}messages.push({role:"assistant",content:data.answer});addMessage("assistant",data.answer,data.visualization);await loadHistory()}catch(error){showError(chatError,error?.message||"A conexão foi interrompida após uma nova tentativa automática. Tente novamente em instantes.")}finally{typing(false);busy=false;send.disabled=false}}
    send.addEventListener("click",()=>ask());draft.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();ask()}});$("suggestions").addEventListener("click",e=>{if(e.target.tagName==="BUTTON")ask(e.target.textContent)});$("new-conversation").addEventListener("click",showHome);$("home-button").addEventListener("click",showHome);$("nav-toggle").addEventListener("click",()=>$("chat-nav").classList.toggle("open"));$("manage-users").addEventListener("click",async()=>{$("admin-modal").classList.remove("hidden");await loadAdmin()});$("close-admin").addEventListener("click",()=>$("admin-modal").classList.add("hidden"));$("admin-modal").addEventListener("click",event=>{if(event.target===$("admin-modal"))$("admin-modal").classList.add("hidden")});$("invite-role").addEventListener("change",updateInviteScope);$("invite-form").addEventListener("submit",async event=>{event.preventDefault();const role=$("invite-role").value,team_keys=selectedTeams($("invite-teams")),button=event.currentTarget.querySelector("button[type=submit]");showError($("admin-error"),"");button.disabled=true;const res=await authedRequest("/api/admin/users",{method:"POST",body:{display_name:$("invite-name").value,email:$("invite-email").value,access_role:role,team_keys,portal_origin:location.origin}}),data=await res.json().catch(()=>({}));button.disabled=false;if(!res.ok){showError($("admin-error"),data.error||"Não foi possível enviar o convite.");return}event.currentTarget.reset();await loadAdmin()});$("logout").addEventListener("click",()=>{save(null);profile=null;activeConversationId=null;messages=[];conversation.textContent="";welcome.classList.remove("hidden");conversation.classList.add("hidden");$("history-list").textContent="";showLogin()});
    if(location.pathname==="/reset-password"){save(null);showLogin();showAuthForm("reset");if(!recoveryToken){showError($("reset-error"),fragment.get("error_description")||"Este link de recuperação é inválido ou expirou. Solicite um novo.");$("reset-button").disabled=true}}else{session=read();if(session?.access_token&&session?.refresh_token)showChat();else{save(null);showLogin();showAuthForm("login")}}
